static vm_fault_t drm_gem_shmem_fault(struct vm_fault *vmf)
{
	struct vm_area_struct *vma = vmf->vma;
	struct drm_gem_object *obj = vma->vm_private_data;
	struct drm_gem_shmem_object *shmem = to_drm_gem_shmem_obj(obj);
	loff_t num_pages = obj->size >> PAGE_SHIFT;
	vm_fault_t ret;
	struct page *page;
	pgoff_t page_offset;  // [!code highlight]

	page_offset = (vmf->address - vma->vm_start) >> PAGE_SHIFT;  // [!code highlight]

	dma_resv_lock(shmem->base.resv, NULL);

	if (page_offset >= num_pages ||  // [!code highlight]
	    drm_WARN_ON_ONCE(obj->dev, !shmem->pages) ||
	    shmem->madv < 0) {
		ret = VM_FAULT_SIGBUS;
	} else {
		page = shmem->pages[page_offset];  // [!code highlight]

		ret = vmf_insert_pfn(vma, vmf->address, page_to_pfn(page));  // [!code highlight]
	}

	dma_resv_unlock(shmem->base.resv);

	return ret;
}
```

> **소스** <a href="https://github.com/torvalds/linux/blob/v6.19/drivers/gpu/drm/drm_gem_shmem_helper.c#L571-L599" target="_blank">drivers/gpu/drm/drm_gem_shmem_helper.c L571-L599</a> (Linux v6.19)

`shmem->pages[page_offset]`가 앞서 `drm_gem_get_pages()`가 모은 배열이고, `vmf_insert_pfn()`이 그 페이지를 유저의 가상 주소에 연결합니다. 이로써 유저의 `*(uint32_t *)(px + ...) = color` 한 줄이 <b>GEM 객체의 shmem 페이지</b>를 직접 쓰게 됩니다.  

